payload.script:
const page = helpers.ensurePage("Automation Playground");
const canvas = helpers.createLayoutFrame({ name: "Automation Output", width: 960, height: 540, layoutMode: "VERTICAL" });
canvas.paddingTop = 64;
canvas.paddingBottom = 64;
canvas.paddingLeft = 96;
canvas.paddingRight = 96;
canvas.itemSpacing = 48;
canvas.fills = [{ type: "SOLID", color: { r: 0.96, g: 0.97, b: 1.0 } }];
page.appendChild(canvas);

const busContainer = figma.createFrame();
busContainer.name = "School Bus";
busContainer.resize(720, 280);
busContainer.cornerRadius = 32;
busContainer.fills = [{ type: "SOLID", color: { r: 1.0, g: 0.8, b: 0.1 } }];
busContainer.strokes = [{ type: "SOLID", color: { r: 0.15, g: 0.15, b: 0.18 } }];
busContainer.strokeWeight = 6;
busContainer.layoutMode = "VERTICAL";
busContainer.primaryAxisSizingMode = "FIXED";
busContainer.counterAxisSizingMode = "AUTO";
busContainer.paddingTop = 32;
busContainer.paddingBottom = 28;
busContainer.paddingLeft = 36;
busContainer.paddingRight = 36;
busContainer.itemSpacing = 28;
canvas.appendChild(busContainer);

const windowsRow = figma.createFrame();
windowsRow.name = "Windows";
windowsRow.layoutMode = "HORIZONTAL";
windowsRow.counterAxisSizingMode = "AUTO";
windowsRow.primaryAxisSizingMode = "AUTO";
windowsRow.itemSpacing = 18;
windowsRow.paddingLeft = 0;
windowsRow.paddingRight = 0;
windowsRow.paddingTop = 0;
windowsRow.paddingBottom = 0;
windowsRow.fills = [];
busContainer.appendChild(windowsRow);

const windowIds = [];
for (let i = 0; i < 4; i++) {
  const windowRect = figma.createRectangle();
  windowRect.resize(120, 90);
  windowRect.cornerRadius = 16;
  windowRect.fills = [{ type: "SOLID", color: { r: 0.86, g: 0.93, b: 0.99 } }];
  windowRect.strokes = [{ type: "SOLID", color: { r: 0.3, g: 0.4, b: 0.55 } }];
  windowRect.strokeWeight = 2;
  windowsRow.appendChild(windowRect);
  windowIds.push(windowRect.id);
}

const stripe = figma.createRectangle();
stripe.resize(busContainer.width, 36);
stripe.cornerRadius = 12;
stripe.fills = [{ type: "SOLID", color: { r: 0.05, g: 0.05, b: 0.05 } }];
busContainer.appendChild(stripe);

await helpers.loadFont({ family: "Inter", style: "Bold" });
const label = figma.createText();
label.characters = "SCHOOL BUS";
label.fontSize = 48;
label.fills = [{ type: "SOLID", color: { r: 1.0, g: 0.95, b: 0.75 } }];
label.textCase = "UPPER";
label.textAlignHorizontal = "CENTER";
label.layoutAlign = "STRETCH";
busContainer.appendChild(label);

const wheelsRow = figma.createFrame();
wheelsRow.name = "Wheels";
wheelsRow.layoutMode = "HORIZONTAL";
wheelsRow.counterAxisSizingMode = "AUTO";
wheelsRow.primaryAxisSizingMode = "AUTO";
wheelsRow.itemSpacing = 320;
wheelsRow.paddingTop = 0;
wheelsRow.paddingBottom = 0;
wheelsRow.paddingLeft = 24;
wheelsRow.paddingRight = 24;
wheelsRow.fills = [];
canvas.appendChild(wheelsRow);

const wheelIds = [];
for (let i = 0; i < 2; i++) {
  const wheelFrame = figma.createFrame();
  wheelFrame.name = `Wheel ${i + 1}`;
  wheelFrame.resize(160, 160);
  wheelFrame.clipsContent = false;
  wheelFrame.fills = [];
  wheelFrame.strokes = [];
  wheelFrame.layoutMode = "NONE";

  const tire = figma.createEllipse();
  tire.resize(160, 160);
  tire.fills = [{ type: "SOLID", color: { r: 0.07, g: 0.07, b: 0.07 } }];
  tire.strokes = [{ type: "SOLID", color: { r: 0.12, g: 0.12, b: 0.12 } }];
  tire.strokeWeight = 6;
  wheelFrame.appendChild(tire);

  const rim = figma.createEllipse();
  rim.resize(92, 92);
  rim.x = 34;
  rim.y = 34;
  rim.fills = [{ type: "SOLID", color: { r: 0.82, g: 0.85, b: 0.9 } }];
  rim.strokes = [{ type: "SOLID", color: { r: 0.65, g: 0.68, b: 0.72 } }];
  rim.strokeWeight = 4;
  wheelFrame.appendChild(rim);

  wheelsRow.appendChild(wheelFrame);
  wheelIds.push(wheelFrame.id);
}

return {
  pageId: page.id,
  canvasId: canvas.id,
  busId: busContainer.id,
  windowIds,
  wheelIds
};
